inline Real length(const PointR&v){return std::sqrt(std::max<Real>(0,norm2(v)));}
inline Real distance(const PointR&a,const PointR&b){return length(a-b);}
inline PointR rotate(const PointR&p,Real angle){Real c=std::cos(angle),s=std::sin(angle);return{p.x*c-p.y*s,p.x*s+p.y*c};}
