inline std::vector<PointI> convex_hull(std::vector<PointI>p,bool include_collinear=true){std::sort(p.begin(),p.end(),[](auto&a,auto&b){return a.x<b.x||(a.x==b.x&&a.y<b.y);});p.erase(std::unique(p.begin(),p.end(),[](auto&a,auto&b){return a.x==b.x&&a.y==b.y;}),p.end());if(p.size()<=1)return p;if(include_collinear){bool all=true;for(size_t i=2;i<p.size();++i)if(orient(p[0],p.back(),p[i])!=0){all=false;break;}if(all)return p;}std::vector<PointI>h;auto bad=[&](const PointI&a,const PointI&b,const PointI&c){int o=orient(a,b,c);return include_collinear?o<0:o<=0;};for(auto&q:p){while(h.size()>=2&&bad(h[h.size()-2],h.back(),q))h.pop_back();h.push_back(q);}size_t t=h.size()+1;for(int i=(int)p.size()-2;i>=0;--i){auto q=p[i];while(h.size()>=t&&bad(h[h.size()-2],h.back(),q))h.pop_back();h.push_back(q);}h.pop_back();if(include_collinear&&h.size()==2&&p.size()>2)return p;return h;}
inline std::vector<PointR> convex_hull(std::vector<PointR>p,bool include_collinear=false,Real eps=1e-12L){std::sort(p.begin(),p.end(),[](auto&a,auto&b){return a.x<b.x||(a.x==b.x&&a.y<b.y);});p.erase(std::unique(p.begin(),p.end(),[&](auto&a,auto&b){return std::fabs(a.x-b.x)<=eps&&std::fabs(a.y-b.y)<=eps;}),p.end());if(p.size()<=1)return p;if(include_collinear){bool all=true;PointR d=p.back()-p[0];for(size_t i=1;i+1<p.size();++i)if(std::fabs(cross(d,p[i]-p[0]))>eps*(1+length(d)*length(p[i]-p[0]))){all=false;break;}if(all)return p;}std::vector<PointR>h;auto bad=[&](const PointR&a,const PointR&b,const PointR&c){Real z=cross(b-a,c-b);return include_collinear?z<-eps:z<=eps;};for(auto&q:p){while(h.size()>=2&&bad(h[h.size()-2],h.back(),q))h.pop_back();h.push_back(q);}size_t t=h.size()+1;for(int i=(int)p.size()-2;i>=0;--i){auto q=p[i];while(h.size()>=t&&bad(h[h.size()-2],h.back(),q))h.pop_back();h.push_back(q);}h.pop_back();return h;}
