inline Real convex_diameter(const std::vector<PointR>&p){int n=(int)p.size();if(n<2)return 0;if(n==2)return distance(p[0],p[1]);int j=1;Real ans=0;for(int i=0;i<n;++i){int ni=(i+1)%n;while(std::fabs(cross(p[ni]-p[i],p[(j+1)%n]-p[j]))>1e-18L&&cross(p[ni]-p[i],p[(j+1)%n]-p[j])>0)j=(j+1)%n;ans=std::max(ans,std::max(distance(p[i],p[j]),distance(p[ni],p[j])));}return ans;}
inline std::vector<PointR> convex_cut(const std::vector<PointR>&p,const PointR&a,const PointR&b,Real eps=1e-12L){std::vector<PointR>r;for(size_t i=0;i<p.size();++i){PointR x=p[i],y=p[(i+1)%p.size()];Real c1=cross(b-a,x-a),c2=cross(b-a,y-a);bool i1=c1>=-eps,i2=c2>=-eps;if(i1)r.push_back(x);if(i1!=i2){Real t=c1/(c1-c2);r.push_back(x+(y-x)*t);}}return r;}
