inline Real closest_pair_distance(std::vector<PointR>p){if(p.size()<2)return std::numeric_limits<Real>::infinity();std::sort(p.begin(),p.end(),[](auto&a,auto&b){return a.x<b.x||(a.x==b.x&&a.y<b.y);});std::vector<PointR>tmp(p.size());std::function<Real(int,int)>rec=[&](int l,int r){if(r-l<=3){Real d=std::numeric_limits<Real>::infinity();for(int i=l;i<r;++i)for(int j=i+1;j<r;++j)d=std::min(d,distance(p[i],p[j]));std::sort(p.begin()+l,p.begin()+r,[](auto&a,auto&b){return a.y<b.y;});return d;}int m=(l+r)/2;Real x=p[m].x,d=std::min(rec(l,m),rec(m,r));std::merge(p.begin()+l,p.begin()+m,p.begin()+m,p.begin()+r,tmp.begin(),[](auto&a,auto&b){return a.y<b.y;});std::copy(tmp.begin(),tmp.begin()+(r-l),p.begin()+l);std::vector<PointR>b;for(int i=l;i<r;++i)if(std::fabs(p[i].x-x)<d){for(int j=(int)b.size()-1;j>=0&&p[i].y-b[j].y<d;--j)d=std::min(d,distance(p[i],b[j]));b.push_back(p[i]);}return d;};return rec(0,(int)p.size());}
