class KdTree2D{struct N{PointI p;int id,l=-1,r=-1;long long mnx,mxx,mny,mxy;};std::vector<N>v;int root=-1;int build(int l,int r,int dep){if(l>=r)return-1;int m=(l+r)/2;std::nth_element(v.begin()+l,v.begin()+m,v.begin()+r,[&](const N&a,const N&b){return dep%2?a.p.y<b.p.y:a.p.x<b.p.x;});int q=m;v[q].l=build(l,m,dep+1);v[q].r=build(m+1,r,dep+1);v[q].mnx=v[q].mxx=v[q].p.x;v[q].mny=v[q].mxy=v[q].p.y;for(int c:{v[q].l,v[q].r})if(c>=0){v[q].mnx=std::min(v[q].mnx,v[c].mnx);v[q].mxx=std::max(v[q].mxx,v[c].mxx);v[q].mny=std::min(v[q].mny,v[c].mny);v[q].mxy=std::max(v[q].mxy,v[c].mxy);}return q;}void query(int q,long long sx,long long tx,long long sy,long long ty,std::vector<int>&out)const{if(q<0||v[q].mxx<sx||tx<v[q].mnx||v[q].mxy<sy||ty<v[q].mny)return;if(sx<=v[q].p.x&&v[q].p.x<=tx&&sy<=v[q].p.y&&v[q].p.y<=ty)out.push_back(v[q].id);query(v[q].l,sx,tx,sy,ty,out);query(v[q].r,sx,tx,sy,ty,out);}public:KdTree2D()=default;explicit KdTree2D(const std::vector<PointI>&p){reset(p);}void reset(const std::vector<PointI>&p){v.clear();v.reserve(p.size());for(int i=0;i<(int)p.size();++i)v.push_back({p[i],i,-1,-1,p[i].x,p[i].x,p[i].y,p[i].y});root=build(0,(int)v.size(),0);}std::vector<int> range_search(long long sx,long long tx,long long sy,long long ty)const{std::vector<int>r;query(root,sx,tx,sy,ty,r);std::sort(r.begin(),r.end());return r;}};
inline long long count_manhattan_segment_intersections(const std::vector<AxisAlignedSegmentI>&s){struct E{long long x,y1,y2;int t;};std::vector<E>e;std::vector<long long>ys;for(auto z:s){long long x1=z.a.x,x2=z.b.x,y1=z.a.y,y2=z.b.y;if(x1>x2)std::swap(x1,x2);if(y1>y2)std::swap(y1,y2);if(y1==y2){e.push_back({x1,y1,y1,0});e.push_back({x2,y1,y1,2});ys.push_back(y1);}else e.push_back({x1,y1,y2,1});}std::sort(ys.begin(),ys.end());ys.erase(std::unique(ys.begin(),ys.end()),ys.end());std::sort(e.begin(),e.end(),[](auto&a,auto&b){return a.x<b.x||(a.x==b.x&&a.t<b.t);});std::vector<int>bit(ys.size()+1);auto add=[&](int i,int z){for(++i;i<(int)bit.size();i+=i&-i)bit[i]+=z;};auto sum=[&](int i){int r=0;for(;i>0;i-=i&-i)r+=bit[i];return r;};long long ans=0;for(auto z:e)if(z.t==1){int l=std::lower_bound(ys.begin(),ys.end(),z.y1)-ys.begin(),r=std::upper_bound(ys.begin(),ys.end(),z.y2)-ys.begin();ans+=sum(r)-sum(l);}else{int i=std::lower_bound(ys.begin(),ys.end(),z.y1)-ys.begin();add(i,z.t==0?1:-1);}return ans;}
