struct HalfPlaneR{PointR a{},b{};};class TranslatedConvexIntersectionI{struct E{PointI a,e;__int128 z;};std::vector<E>v;public:TranslatedConvexIntersectionI()=default;TranslatedConvexIntersectionI(const std::vector<PointI>&p,const std::vector<PointI>&t){reset(p,t);}void reset(std::vector<PointI>p,const std::vector<PointI>&t){v.clear();if(p.size()<3||t.empty())return;if(polygon_area2_exact(p)<0)std::reverse(p.begin(),p.end());v.reserve(p.size());for(size_t i=0;i<p.size();++i){PointI a=p[i],b=p[(i+1)%p.size()],e{b.x-a.x,b.y-a.y};__int128 z=-((__int128)1<<126);for(auto q:t)z=std::max(z,(__int128)e.x*q.y-(__int128)e.y*q.x);v.push_back({a,e,z});}}bool contains(const PointI&q)const{if(v.empty())return false;for(auto&x:v)if((__int128)x.e.x*(q.y-x.a.y)-(__int128)x.e.y*(q.x-x.a.x)<x.z)return false;return true;}size_t edge_count()const{return v.size();}};
