inline long long parse_fixed_decimal(const std::string&s,int digits=4){size_t i=0;bool neg=false;if(i<s.size()&&(s[i]=='-'||s[i]=='+')){neg=s[i]=='-';++i;}long long a=0;while(i<s.size()&&s[i]!='.')a=a*10+(s[i++]-'0');long long f=0,p=1;if(i<s.size())++i;for(int k=0;k<digits;++k){f*=10;if(i<s.size())f+=s[i++]-'0';p*=10;}long long v=a*p+f;return neg?-v:v;}
