inline PointR polygon_centroid(const std::vector<PointR>&p){if(p.empty())return{};Real a=0,cx=0,cy=0;for(size_t i=0;i<p.size();++i){const auto&u=p[i];const auto&v=p[(i+1)%p.size()];Real z=cross(u,v);a+=z;cx+=(u.x+v.x)*z;cy+=(u.y+v.y)*z;}if(std::fabs(a)<=1e-24L){PointR c{};for(auto q:p)c=c+q;return c/Real(p.size());}return{cx/(3*a),cy/(3*a)};}

struct OrientedRectangleR{std::array<PointR,4>corners{};Real area{0},width{0},height{0},angle{0};};
inline Real convex_polygon_minimum_width(const std::vector<PointR>&input){auto p=convex_hull(input,false);int n=(int)p.size();if(n<3)return 0;Real ans=std::numeric_limits<Real>::infinity();for(int i=0;i<n;++i){PointR e=p[(i+1)%n]-p[i];Real l=length(e);if(l==0)continue;Real lo=std::numeric_limits<Real>::infinity(),hi=-lo;for(auto q:p){Real z=cross(e,q-p[i])/l;lo=std::min(lo,z);hi=std::max(hi,z);}ans=std::min(ans,hi-lo);}return ans;}
inline OrientedRectangleR minimum_area_bounding_rectangle(const std::vector<PointR>&input){auto p=convex_hull(input,false);OrientedRectangleR best;if(p.empty())return best;if(p.size()==1){best.corners.fill(p[0]);return best;}best.area=std::numeric_limits<Real>::infinity();for(size_t i=0;i<p.size();++i){PointR e=p[(i+1)%p.size()]-p[i];Real l=length(e);if(l==0)continue;PointR u=e/l,v{-u.y,u.x};Real u0=std::numeric_limits<Real>::infinity(),u1=-u0,v0=u0,v1=-u0;for(auto q:p){Real a=dot(q,u),b=dot(q,v);u0=std::min(u0,a);u1=std::max(u1,a);v0=std::min(v0,b);v1=std::max(v1,b);}Real w=u1-u0,h=v1-v0,A=w*h;if(A<best.area){best.area=A;best.width=w;best.height=h;best.angle=std::atan2(u.y,u.x);best.corners={u*u0+v*v0,u*u1+v*v0,u*u1+v*v1,u*u0+v*v1};}}if(!std::isfinite(best.area))best.area=0;return best;}

inline std::vector<PointI> minkowski_sum_convex(std::vector<PointI>a,std::vector<PointI>b){a=convex_hull(std::move(a),false);b=convex_hull(std::move(b),false);if(a.empty()||b.empty())return{};if(a.size()==1){for(auto&x:b){x.x+=a[0].x;x.y+=a[0].y;}return b;}if(b.size()==1){for(auto&x:a){x.x+=b[0].x;x.y+=b[0].y;}return a;}auto rot=[](std::vector<PointI>&p){int k=0;for(int i=1;i<(int)p.size();++i)if(std::tie(p[i].y,p[i].x)<std::tie(p[k].y,p[k].x))k=i;std::rotate(p.begin(),p.begin()+k,p.end());};rot(a);rot(b);std::vector<PointI>ea,eb;for(size_t i=0;i<a.size();++i)ea.push_back(a[(i+1)%a.size()]-a[i]);for(size_t i=0;i<b.size();++i)eb.push_back(b[(i+1)%b.size()]-b[i]);std::vector<PointI>r{{a[0].x+b[0].x,a[0].y+b[0].y}};size_t i=0,j=0;while(i<ea.size()||j<eb.size()){PointI d{};if(j==eb.size())d=ea[i++];else if(i==ea.size())d=eb[j++];else{__int128 z=(__int128)ea[i].x*eb[j].y-(__int128)ea[i].y*eb[j].x;if(z>0)d=ea[i++];else if(z<0)d=eb[j++];else{d={ea[i].x+eb[j].x,ea[i].y+eb[j].y};++i;++j;}}r.push_back(r.back()+d);}r.pop_back();return convex_hull(std::move(r),false);}
inline std::vector<PointR> minkowski_sum_convex(std::vector<PointR>a,std::vector<PointR>b,Real eps=1e-12L){a=convex_hull(std::move(a),false,eps);b=convex_hull(std::move(b),false,eps);if(a.empty()||b.empty())return{};std::vector<PointR>s;for(auto x:a)for(auto y:b)s.push_back(x+y);return convex_hull(std::move(s),false,eps);}

inline Real circle_union_area(std::vector<CircleR>c,Real eps=1e-12L){const Real pi=std::acos(Real(-1));Real ans=0;for(size_t i=0;i<c.size();++i){if(c[i].radius<=0)continue;bool hidden=false;for(size_t j=0;j<c.size();++j)if(i!=j){Real d=distance(c[i].center,c[j].center);if(d+c[i].radius<=c[j].radius+eps*(1+d+c[i].radius+c[j].radius)&&(c[j].radius>c[i].radius+eps||j<i)){hidden=true;break;}}if(hidden)continue;std::vector<std::pair<Real,Real>>seg;for(size_t j=0;j<c.size();++j)if(i!=j){Real d=distance(c[i].center,c[j].center),r=c[i].radius,R=c[j].radius;if(d>=r+R-eps||d+R<=r+eps||d<=eps)continue;Real x=(d*d+r*r-R*R)/(2*d*r);x=std::max<Real>(-1,std::min<Real>(1,x));Real da=std::acos(x),m=std::atan2(c[j].center.y-c[i].center.y,c[j].center.x-c[i].center.x);Real l=m-da,h=m+da;while(l<0){l+=2*pi;h+=2*pi;}while(l>=2*pi){l-=2*pi;h-=2*pi;}if(h<=2*pi)seg.push_back({l,h});else{seg.push_back({l,2*pi});seg.push_back({0,h-2*pi});}}std::sort(seg.begin(),seg.end());std::vector<std::pair<Real,Real>>u;for(auto z:seg){if(u.empty()||z.first>u.back().second+eps)u.push_back(z);else u.back().second=std::max(u.back().second,z.second);}Real at=0;auto add_arc=[&](Real l,Real h){if(h<=l)return;PointR p1=c[i].center+PointR{std::cos(l),std::sin(l)}*c[i].radius,p2=c[i].center+PointR{std::cos(h),std::sin(h)}*c[i].radius;ans+=(cross(c[i].center,p2-p1)+c[i].radius*c[i].radius*(h-l))/2;};for(auto z:u){add_arc(at,z.first);at=std::max(at,z.second);}add_arc(at,2*pi);}return std::fabs(ans);}

inline int convex_layers_count(std::vector<PointI>p){int layers=0;while(p.size()>=3){auto h=convex_hull(p,true);if(h.size()<3)break;++layers;std::set<std::pair<long long,long long>>rm;for(auto q:h)rm.insert({q.x,q.y});std::vector<PointI>n;n.reserve(p.size()-h.size());for(auto q:p)if(!rm.count({q.x,q.y}))n.push_back(q);p.swap(n);}return layers;}

inline __int128 maximum_quadrilateral_area2(const std::vector<PointI>&p){__int128 ans=0;for(size_t i=0;i<p.size();++i)for(size_t j=i+1;j<p.size();++j){__int128 hi=0,lo=0;PointI e=p[j]-p[i];for(size_t k=0;k<p.size();++k){__int128 z=(__int128)e.x*(p[k].y-p[i].y)-(__int128)e.y*(p[k].x-p[i].x);hi=std::max(hi,z);lo=std::min(lo,z);}if(hi>0&&lo<0)ans=std::max(ans,hi-lo);}return ans;}

inline long long count_castle_quadruples(const std::vector<PointI>&p){int n=(int)p.size();if(n<5)return 0;auto C3=[](long long x){return x<3?0:x*(x-1)*(x-2)/6;};auto C4=[](long long x){return x<4?0:x*(x-1)*(x-2)*(x-3)/24;};long long total=0;for(int q=0;q<n;++q){std::vector<PointI>v;v.reserve(n-1);for(int i=0;i<n;++i)if(i!=q)v.push_back(p[i]-p[q]);auto half=[](const PointI&a){return a.y>0||(a.y==0&&a.x>0);};std::sort(v.begin(),v.end(),[&](const PointI&a,const PointI&b){bool A=half(a),B=half(b);if(A!=B)return A>B;__int128 z=(__int128)a.x*b.y-(__int128)a.y*b.x;if(z)return z>0;return (__int128)a.x*a.x+(__int128)a.y*a.y<(__int128)b.x*b.x+(__int128)b.y*b.y;});int m=v.size();v.insert(v.end(),v.begin(),v.end());long long bad=0;int j=0;for(int i=0;i<m;++i){if(j<i+1)j=i+1;while(j<i+m&&(__int128)v[i].x*v[j].y-(__int128)v[i].y*v[j].x>0)++j;bad+=C3(j-i-1);}total+=C4(m)-bad;}return total;}

inline unsigned long long maximum_bottleneck_triangle_distance2(const std::vector<PointI>&p){int n=(int)p.size();if(n<3)return 0;struct E{unsigned long long d;uint32_t a,b;};std::vector<E>e;e.reserve((size_t)n*(n-1)/2);for(int i=0;i<n;++i)for(int j=i+1;j<n;++j){__int128 dx=(__int128)p[i].x-p[j].x,dy=(__int128)p[i].y-p[j].y;unsigned __int128 z=(unsigned __int128)(dx*dx+dy*dy);e.push_back({(unsigned long long)z,(uint32_t)i,(uint32_t)j});}std::sort(e.begin(),e.end(),[](const E&x,const E&y){return x.d>y.d;});int w=(n+63)/64;std::vector<uint64_t>g((size_t)n*w);for(auto x:e){uint64_t*ga=&g[(size_t)x.a*w],*gb=&g[(size_t)x.b*w];for(int k=0;k<w;++k)if(ga[k]&gb[k])return x.d;ga[x.b>>6]|=1ull<<(x.b&63);gb[x.a>>6]|=1ull<<(x.a&63);}return 0;}
inline Real maximum_equal_nonoverlapping_circle_radius(const std::vector<PointI>&p){return std::sqrt((Real)maximum_bottleneck_triangle_distance2(p))/2;}

inline long long maximum_weight_on_line(const std::vector<PointI>&p,const std::vector<long long>&weight){if(p.size()!=weight.size())throw std::invalid_argument("point/weight size mismatch");long long ans=0;for(size_t i=0;i<p.size();++i){std::map<std::pair<long long,long long>,long long>m;for(size_t j=0;j<p.size();++j)if(i!=j){long long dx=p[j].x-p[i].x,dy=p[j].y-p[i].y,g=std::gcd(std::llabs(dx),std::llabs(dy));dx/=g;dy/=g;if(dx<0||(dx==0&&dy<0)){dx=-dx;dy=-dy;}m[{dx,dy}]+=weight[j];}ans=std::max(ans,weight[i]);for(auto&z:m)ans=std::max(ans,weight[i]+z.second);}return std::max(0ll,ans);}

inline long long minimum_collinear_segment_cover(const std::vector<std::pair<PointI,PointI>>&segments){struct K{long long dx,dy;__int128 c;bool operator<(const K&o)const{return std::tie(dx,dy)<std::tie(o.dx,o.dy)||(dx==o.dx&&dy==o.dy&&c<o.c);}};std::map<K,std::vector<std::pair<__int128,__int128>>>m;for(auto s:segments){long long dx=s.second.x-s.first.x,dy=s.second.y-s.first.y,g=std::gcd(std::llabs(dx),std::llabs(dy));if(!g)continue;dx/=g;dy/=g;if(dx<0||(dx==0&&dy<0)){dx=-dx;dy=-dy;}__int128 c=(__int128)dx*s.first.y-(__int128)dy*s.first.x,t1=(__int128)dx*s.first.x+(__int128)dy*s.first.y,t2=(__int128)dx*s.second.x+(__int128)dy*s.second.y;if(t1>t2)std::swap(t1,t2);m[{dx,dy,c}].push_back({t1,t2});}long long ans=0;for(auto&kv:m){auto&v=kv.second;std::sort(v.begin(),v.end());__int128 r=0;bool have=false;for(auto z:v){if(!have||z.first>r){++ans;r=z.second;have=true;}else r=std::max(r,z.second);}}return ans;}


class DynamicConvexHullI{using M=std::map<long long,long long>;M up,down;static PointI pt(M::const_iterator i){return{i->first,i->second};}static bool invalid(const PointI&a,const PointI&b,const PointI&c,bool upper){int z=orient(a,b,c);return upper?z>=0:z<=0;}static void add_chain(M&m,PointI p,bool upper){auto it=m.lower_bound(p.x);if(it!=m.end()&&it->first==p.x){if((upper&&it->second>=p.y)||(!upper&&it->second<=p.y))return;it->second=p.y;}else it=m.emplace_hint(it,p.x,p.y);if(it!=m.begin()){auto l=std::prev(it),r=std::next(it);if(r!=m.end()&&invalid(pt(l),pt(it),pt(r),upper)){m.erase(it);return;}}while(it!=m.begin()){auto b=std::prev(it);if(b==m.begin())break;auto a=std::prev(b);if(!invalid(pt(a),pt(b),pt(it),upper))break;m.erase(b);}for(;;){auto b=std::next(it);if(b==m.end())break;auto c=std::next(b);if(c==m.end()||!invalid(pt(it),pt(b),pt(c),upper))break;m.erase(b);}}static bool below(const M&m,PointI p,bool upper){if(m.empty()||p.x<m.begin()->first||p.x>m.rbegin()->first)return false;auto r=m.lower_bound(p.x);if(r!=m.end()&&r->first==p.x)return upper?p.y<=r->second:p.y>=r->second;if(r==m.begin()||r==m.end())return false;auto l=std::prev(r);int z=orient(pt(l),pt(r),p);return upper?z<=0:z>=0;}public:void clear(){up.clear();down.clear();}void add(PointI p){add_chain(up,p,true);add_chain(down,p,false);}bool contains(PointI p)const{return below(up,p,true)&&below(down,p,false);}size_t upper_size()const{return up.size();}size_t lower_size()const{return down.size();}};

inline bool rectangle_fits_in_rectangle(Real outer_width,Real outer_height,Real inner_width,Real inner_height,bool strict=false){if(outer_width<outer_height)std::swap(outer_width,outer_height);if(inner_width<inner_height)std::swap(inner_width,inner_height);Real e=1e-14L*(1+outer_width+outer_height+inner_width+inner_height);auto le=[&](Real x,Real y){return strict?x<y-e:x<=y+e;};if(le(inner_width,outer_width)&&le(inner_height,outer_height))return true;if(inner_width*inner_width+inner_height*inner_height>outer_width*outer_width+outer_height*outer_height+e)return false;Real l=0,r=acosl(-1)/2;for(int k=0;k<120;++k){Real m1=(2*l+r)/3,m2=(l+2*r)/3;auto f=[&](Real t){return std::max((inner_width*cosl(t)+inner_height*sinl(t))/outer_width,(inner_width*sinl(t)+inner_height*cosl(t))/outer_height);};if(f(m1)<f(m2))r=m2;else l=m1;}Real t=(l+r)/2,w=inner_width*cosl(t)+inner_height*sinl(t),h=inner_width*sinl(t)+inner_height*cosl(t);return le(w,outer_width)&&le(h,outer_height);}
inline long long farthest_manhattan_distance(const std::vector<std::vector<long long>>&points){if(points.empty())return 0;int d=(int)points[0].size();if(d>=63)throw std::invalid_argument("dimension");for(auto&p:points)if((int)p.size()!=d)throw std::invalid_argument("dimension");long long ans=0;for(uint64_t m=0;m<(1ull<<d);++m){__int128 lo=0,hi=0;bool first=true;for(auto&p:points){__int128 z=0;for(int j=0;j<d;++j)z+=(m>>j&1)?p[j]:-(__int128)p[j];if(first)lo=hi=z,first=false;else lo=std::min(lo,z),hi=std::max(hi,z);}__int128 q=hi-lo;if(q>std::numeric_limits<long long>::max())throw std::overflow_error("manhattan");ans=std::max(ans,(long long)q);}return ans;}
inline bool convex_polygons_disjoint(const std::vector<PointR>&a,const std::vector<PointR>&b,bool allow_touch=false,Real eps=1e-12L){if(a.empty()||b.empty())return true;auto sg=[&](Real x){return x>eps?1:x<-eps?-1:0;};for(size_t i=0;i<a.size();++i)for(size_t j=0;j<b.size();++j)if(segments_intersect(a[i],a[(i+1)%a.size()],b[j],b[(j+1)%b.size()],eps)){if(!allow_touch)return false;int x=sg(cross(a[(i+1)%a.size()]-a[i],b[j]-a[i])),y=sg(cross(a[(i+1)%a.size()]-a[i],b[(j+1)%b.size()]-a[i])),u=sg(cross(b[(j+1)%b.size()]-b[j],a[i]-b[j])),v=sg(cross(b[(j+1)%b.size()]-b[j],a[(i+1)%a.size()]-b[j]));if(x*y<0&&u*v<0)return false;}auto x=point_in_polygon(a,b[0],eps),y=point_in_polygon(b,a[0],eps);if(x==PointLocation::Inside||y==PointLocation::Inside)return false;if(!allow_touch&&(x==PointLocation::Boundary||y==PointLocation::Boundary))return false;return true;}
inline __int128 maximum_triangle_area2(std::vector<PointI>p){p=convex_hull(std::move(p),false);int n=(int)p.size();if(n<3)return 0;auto ar=[&](int i,int j,int k){__int128 v=(__int128)(p[j].x-p[i].x)*(p[k].y-p[i].y)-(__int128)(p[j].y-p[i].y)*(p[k].x-p[i].x);return v<0?-v:v;};__int128 ans=0;for(int i=0;i<n-2;++i){int k=i+2;for(int j=i+1;j<n-1;++j){if(k<=j)k=j+1;while(k+1<n&&ar(i,j,k+1)>ar(i,j,k))++k;ans=std::max(ans,ar(i,j,k));}}return ans;}
inline Real minimum_regular_polygon_area_through_three_points(const PointR&a,const PointR&b,const PointR&c,int maximum_sides=1000,Real eps=1e-9L){CircleR o=circumcircle(a,b,c);if(o.radius<0)return std::numeric_limits<Real>::quiet_NaN();const Real pi=acosl(-1);std::array<Real,3>t{atan2l(a.y-o.center.y,a.x-o.center.x),atan2l(b.y-o.center.y,b.x-o.center.x),atan2l(c.y-o.center.y,c.x-o.center.x)};for(auto&x:t)if(x<0)x+=2*pi;std::sort(t.begin(),t.end());std::array<Real,3>g{t[1]-t[0],t[2]-t[1],2*pi-t[2]+t[0]};for(int n=3;n<=maximum_sides;++n){Real u=2*pi/n;bool ok=true;for(Real x:g)if(std::fabs(x/u-std::round(x/u))>eps)ok=false;if(ok)return n*o.radius*o.radius*sinl(2*pi/n)/2;}return std::numeric_limits<Real>::quiet_NaN();}


struct TriangleTypeCounts{long long acute{0},right{0},obtuse{0},degenerate{0};};
inline TriangleTypeCounts count_triangle_types(const std::vector<PointI>&input){
    struct V{__int128 x,y;long long w;};
    auto cr=[](const V&a,const V&b){auto u=f4a(a.x,b.y),v=f4a(a.y,b.x);v.first=-v.first;return f4b(u,v);};
    auto dt=[](const V&a,const V&b){return f4b(f4a(a.x,b.x),f4a(a.y,b.y));};
    auto half=[](const V&a){return a.y>0||(a.y==0&&a.x>0);};
    auto mag=[](__int128 x){return x<0?(__uint128_t)(-(x+1))+1:(__uint128_t)x;};
    auto gcd128=[&](__int128 a,__int128 b){__uint128_t x=mag(a),y=mag(b);while(y){auto z=x%y;x=y;y=z;}return x;};
    std::map<std::pair<long long,long long>,long long>freq;for(auto p:input)++freq[{p.x,p.y}];
    std::vector<PointI>p;std::vector<long long>w;p.reserve(freq.size());w.reserve(freq.size());for(auto [q,z]:freq){p.push_back({q.first,q.second});w.push_back(z);}
    long long n=(long long)input.size();auto C2=[](__int128 x){return x*(x-1)/2;};auto C3=[](__int128 x){return x*(x-1)*(x-2)/6;};
    __int128 repeated=0;for(long long z:w)repeated+=C3(z)+C2(z)*(n-z);
    __int128 right=0,obtuse=0,collinear_pivot_pairs=0;int u=(int)p.size();
    for(int o=0;o<u;++o){
        std::vector<V>v;v.reserve(u-1);std::vector<V>d;d.reserve(u-1);
        for(int i=0;i<u;++i)if(i!=o){V q{(__int128)p[i].x-p[o].x,(__int128)p[i].y-p[o].y,w[i]};v.push_back(q);auto g=gcd128(q.x,q.y);q.x/=(__int128)g;q.y/=(__int128)g;if(q.x<0||(q.x==0&&q.y<0)){q.x=-q.x;q.y=-q.y;}d.push_back(q);}
        std::sort(d.begin(),d.end(),[](const V&a,const V&b){return a.x<b.x||(a.x==b.x&&a.y<b.y);});
        for(int l=0,r;l<(int)d.size();l=r){__int128 sum=0,squares=0;for(r=l;r<(int)d.size()&&d[r].x==d[l].x&&d[r].y==d[l].y;++r){sum+=d[r].w;squares+=(__int128)d[r].w*d[r].w;}collinear_pivot_pairs+=(__int128)w[o]*(sum*sum-squares)/2;}
        std::sort(v.begin(),v.end(),[&](const V&a,const V&b){bool A=half(a),B=half(b);if(A!=B)return A>B;int z=cr(a,b);if(z)return z>0;long double aa=(long double)a.x*a.x+(long double)a.y*a.y,bb=(long double)b.x*b.x+(long double)b.y*b.y;return aa<bb;});
        int m=(int)v.size();v.insert(v.end(),v.begin(),v.end());std::vector<__int128>pref(v.size()+1);for(size_t i=0;i<v.size();++i)pref[i+1]=pref[i]+v[i].w;int p0=1,p90=1,p90e=1,p180=1;
        for(int i=0;i<m;++i){p0=std::max(p0,i+1);while(p0<i+m&&cr(v[i],v[p0])==0&&dt(v[i],v[p0])>0)++p0;p90=std::max(p90,p0);while(p90<i+m&&cr(v[i],v[p90])>0&&dt(v[i],v[p90])>0)++p90;p90e=std::max(p90e,p90);while(p90e<i+m&&cr(v[i],v[p90e])>0&&dt(v[i],v[p90e])==0)++p90e;p180=std::max(p180,p90e);while(p180<i+m&&cr(v[i],v[p180])>0)++p180;right+=(__int128)w[o]*v[i].w*(pref[p90e]-pref[p90]);obtuse+=(__int128)w[o]*v[i].w*(pref[p180]-pref[p90e]);}
    }
    __int128 deg=repeated+collinear_pivot_pairs/3,total=C3(n),acute=total-deg-right-obtuse;return{(long long)acute,(long long)right,(long long)obtuse,(long long)deg};
}
inline Real maximum_angle_radians(const std::vector<PointR>&p){const Real pi=acosl(-1);Real ans=0;int n=(int)p.size();for(int o=0;o<n;++o){std::vector<Real>a;a.reserve(n-1);for(int i=0;i<n;++i)if(i!=o){Real t=atan2l(p[i].y-p[o].y,p[i].x-p[o].x);if(t<0)t+=2*pi;a.push_back(t);}std::sort(a.begin(),a.end());for(Real x:a){Real target=x+pi;if(target>=2*pi)target-=2*pi;auto it=std::lower_bound(a.begin(),a.end(),target);for(int k=-1;k<=1;++k){int j=(it-a.begin()+k+(int)a.size())%(int)a.size();Real d=fabsl(a[j]-x);d=std::min(d,2*pi-d);ans=std::max(ans,d);}}}return ans;}
