inline std::vector<Real> nearest_site_direction_probabilities(const std::vector<PointI>&p){int n=(int)p.size();std::vector<Real>ans(n);if(!n)return ans;if(n==1){ans[0]=1;return ans;}struct Q{PointI p;int id;};std::vector<Q>a(n);for(int i=0;i<n;++i)a[i]={p[i],i};std::sort(a.begin(),a.end(),[](const Q&x,const Q&y){return x.p.x<y.p.x||(x.p.x==y.p.x&&(x.p.y<y.p.y||(x.p.y==y.p.y&&x.id<y.id)));});std::vector<Q>h;for(auto q:a){while(h.size()>=2&&orient(h[h.size()-2].p,h.back().p,q.p)<=0)h.pop_back();h.push_back(q);}size_t z=h.size();for(int i=n-2;i>=0;--i){while(h.size()>z&&orient(h[h.size()-2].p,h.back().p,a[i].p)<=0)h.pop_back();h.push_back(a[i]);}if(h.size()>1)h.pop_back();if(h.size()==2){ans[h[0].id]=ans[h[1].id]=0.5L;return ans;}const Real pi=acosl(-1);for(int i=0,m=(int)h.size();i<m;++i){PointR u{(Real)(h[(i-1+m)%m].p.x-h[i].p.x),(Real)(h[(i-1+m)%m].p.y-h[i].p.y)},v{(Real)(h[(i+1)%m].p.x-h[i].p.x),(Real)(h[(i+1)%m].p.y-h[i].p.y)};Real interior=angle_between(u,v);ans[h[i].id]=(pi-interior)/(2*pi);}return ans;}
inline Real right_circular_cone_volume(Real radius,Real height){return acosl(-1)*radius*radius*height/3;}
inline Real right_circular_cone_volume_prefix(Real base_x,Real radius,Real height,Real x){if(height<=0||radius<0)return std::numeric_limits<Real>::quiet_NaN();if(x<=base_x)return 0;if(x>=base_x+height)return right_circular_cone_volume(radius,height);Real u=(x-base_x)/height;return right_circular_cone_volume(radius,height)*(1-(1-u)*(1-u)*(1-u));}
