inline bool weighted_distance_k_feasible(const std::vector<PointR>&points,const std::vector<Real>&coefficient,int k,Real time,Real eps=1e-11L){int n=(int)points.size();if((int)coefficient.size()!=n||k<0||k>n||time<0)return false;if(k==0)return true;std::vector<PointR>candidate=points;candidate.reserve(n+n*(n-1));for(int i=0;i<n;++i){if(!(coefficient[i]>0))return false;for(int j=i+1;j<n;++j){Real ri=time/coefficient[i],rj=time/coefficient[j];auto q=circle_circle_intersection(points[i],ri*ri,points[j],rj*rj);if(q.kind==IntersectionKind::One)candidate.push_back(q.first);else if(q.kind==IntersectionKind::Two){candidate.push_back(q.first);candidate.push_back(q.second);}}}for(const auto&q:candidate){int count=0;for(int i=0;i<n;++i)if(coefficient[i]*distance(q,points[i])<=time+eps*(1+time))++count;if(count>=k)return true;}return false;}
inline Real minimum_kth_weighted_distance(const std::vector<PointR>&points,const std::vector<Real>&coefficient,int k,int iterations=100){int n=(int)points.size();if((int)coefficient.size()!=n||k<1||k>n)return std::numeric_limits<Real>::quiet_NaN();for(Real c:coefficient)if(!(c>0))return std::numeric_limits<Real>::quiet_NaN();if(weighted_distance_k_feasible(points,coefficient,k,0))return 0;Real lo=0,hi=1;for(int z=0;z<200&&!weighted_distance_k_feasible(points,coefficient,k,hi);++z)hi*=2;if(!std::isfinite(hi))return hi;for(int z=0;z<iterations;++z){Real mid=(lo+hi)/2;if(weighted_distance_k_feasible(points,coefficient,k,mid))hi=mid;else lo=mid;}return hi;}
struct MovingPointDistanceResult{Real time{0},distance{0};PointR first{},second{};};
inline MovingPointDistanceResult minimum_distance_between_moving_points(const PointR&a0,const PointR&a1,const PointR&b0,const PointR&b1,Real start_time=0,Real end_time=1){if(start_time>end_time)std::swap(start_time,end_time);PointR r0=a0-b0,rv=(a1-a0)-(b1-b0);Real duration=end_time-start_time,u=0,z=norm2(rv);if(z>0)u=std::clamp(-dot(r0,rv)/z,Real(0),Real(1));PointR a=a0+(a1-a0)*u,b=b0+(b1-b0)*u;return{start_time+duration*u,distance(a,b),a,b};}
inline bool is_triangle_sides(Real a,Real b,Real c,Real eps=1e-12L){if(a<=0||b<=0||c<=0)return false;Real s=std::max({a,b,c});return a+b>c-eps*s&&b+c>a-eps*s&&c+a>b-eps*s;}
inline bool is_right_triangle_sides(long long a,long long b,long long c){if(a<=0||b<=0||c<=0)return false;std::array<__int128,3>x{a,b,c};std::sort(x.begin(),x.end());return x[0]*x[0]+x[1]*x[1]==x[2]*x[2];}
inline std::array<Integer,3> pythagorean_triple_with_leg(long long leg){if(leg<3)throw std::invalid_argument("leg");Integer x=leg,y,z;if(leg&1){y=(x*x-1)/2;z=(x*x+1)/2;}else{y=x*x/4-1;z=x*x/4+1;}return{x,y,z};}
