inline PointI normalize_direction(PointI v){if(v.x==0&&v.y==0)return v;long long g=std::gcd(std::llabs(v.x),std::llabs(v.y));return{v.x/g,v.y/g};}namespace detail{inline int f5a(PointI v){return v.y>0||(v.y==0&&v.x>=0)?0:1;}inline bool f5b(PointI a,PointI b){return orient(PointI{0,0},a,b)==0&&(__int128)a.x*b.x+(__int128)a.y*b.y>0;}}inline bool polar_angle_less(PointI a,PointI b){int x=detail::f5a(a),y=detail::f5a(b);if(x!=y)return x<y;return orient(PointI{0,0},a,b)>0;}inline void sort_by_polar_angle(std::vector<PointI>&v){std::sort(v.begin(),v.end(),polar_angle_less);}
class PolarDirectionCounterI{std::vector<PointI>d;std::vector<long long>p;size_t f(PointI v)const{v=normalize_direction(v);return std::lower_bound(d.begin(),d.end(),v,polar_angle_less)-d.begin();}size_t g(PointI v)const{v=normalize_direction(v);return std::upper_bound(d.begin(),d.end(),v,[](PointI x,PointI y){return polar_angle_less(x,y);})-d.begin();}public:void reset(const std::vector<PointI>&v){std::vector<std::pair<PointI,long long>>a;a.reserve(v.size());for(auto q:v)if(q.x||q.y)a.push_back({normalize_direction(q),1});reset(a);}void reset(const std::vector<std::pair<PointI,long long>>&v){std::vector<std::pair<PointI,long long>>a;for(auto q:v){if(q.second<0)throw std::invalid_argument("negative weight");if((q.first.x||q.first.y)&&q.second)a.push_back({normalize_direction(q.first),q.second});}std::sort(a.begin(),a.end(),[](auto&x,auto&y){return polar_angle_less(x.first,y.first);});d.clear();p.assign(1,0);for(auto q:a){if(!d.empty()&&detail::f5b(d.back(),q.first))p.back()+=q.second;else{d.push_back(q.first);p.push_back(p.back()+q.second);}}}long long total_weight()const{return p.empty()?0:p.back();}size_t distinct_direction_count()const{return d.size();}long long direction_weight(PointI v)const{if(v.x==0&&v.y==0)return 0;v=normalize_direction(v);size_t i=f(v);return i<d.size()&&detail::f5b(d[i],v)?p[i+1]-p[i]:0;}long long count_counterclockwise_inclusive(PointI a,PointI b)const{if(d.empty()||(!a.x&&!a.y)||(!b.x&&!b.y))return 0;a=normalize_direction(a);b=normalize_direction(b);if(detail::f5b(a,b))return direction_weight(a);size_t l=f(a),r=g(b);if(!polar_angle_less(b,a))return p[r]-p[l];return total_weight()-p[l]+p[r];}long long count_clockwise_inclusive(PointI a,PointI b)const{return count_counterclockwise_inclusive(b,a);}};

inline IntersectionResult<PointR>segment_circle_intersection(const PointR&a,const PointR&b,const PointR&o,Real radius_squared,Real eps=1e-12L){PointR d=b-a;if(norm2(d)<=eps){Real z=norm2(a-o)-radius_squared;if(std::fabs(z)<=eps*(1+std::fabs(radius_squared)))return{IntersectionKind::One,a,a};return{IntersectionKind::None,{},{}};}auto q=line_circle_intersection(a,b,o,radius_squared,eps);if(q.kind==IntersectionKind::None||q.kind==IntersectionKind::Degenerate)return q;std::vector<PointR>x;auto add=[&](PointR p){Real t=dot(p-a,d)/norm2(d);if(t<-eps||t>1+eps)return;for(auto z:x)if(distance(z,p)<=eps*(1+length(d)))return;x.push_back(p);};add(q.first);if(q.kind==IntersectionKind::Two)add(q.second);if(x.empty())return{IntersectionKind::None,{},{}};if(x.size()==1)return{IntersectionKind::One,x[0],x[0]};return{IntersectionKind::Two,x[0],x[1]};}

inline bool segment_intersects_convex_polygon_interior(const std::vector<PointR>&polygon,const PointR&a,const PointR&b,Real eps=1e-12L){int n=(int)polygon.size();if(n<3)return false;if(point_in_convex_polygon(polygon,a,eps)==PointLocation::Inside||point_in_convex_polygon(polygon,b,eps)==PointLocation::Inside)return true;PointR d=b-a;Real lo=0,hi=1;for(int i=0;i<n;++i){PointR e=polygon[(i+1)%n]-polygon[i];Real f0=cross(e,a-polygon[i]),fd=cross(e,d);Real sc=eps*(1+length(e)*(1+length(a-polygon[i])+length(d)));if(std::fabs(fd)<=sc){if(f0<-sc)return false;continue;}Real t=-f0/fd;if(fd>0)lo=std::max(lo,t);else hi=std::min(hi,t);if(lo>hi+eps)return false;}lo=std::max(lo,Real(0));hi=std::min(hi,Real(1));if(hi-lo<=eps)return false;PointR m=a+d*((lo+hi)/2);return point_in_convex_polygon(polygon,m,eps)==PointLocation::Inside;}
inline std::vector<int>convex_polygon_visible_vertices_ccw(const std::vector<PointR>&polygon,const PointR&p,Real eps=1e-12L){std::vector<int>r;int n=(int)polygon.size();if(n<1)return r;if(n<3){for(int i=0;i<n;++i)r.push_back(i);return r;}if(point_in_convex_polygon(polygon,p,eps)!=PointLocation::Outside)return r;for(int i=0;i<n;++i){PointR u=polygon[i]-polygon[(i+n-1)%n],v=polygon[(i+1)%n]-polygon[i],w=p-polygon[i];Real a=cross(u,w),b=cross(v,w),sc=eps*(1+length(w)*(length(u)+length(v)));if(a<=sc||b<=sc)r.push_back(i);}return r;}
