inline ConvexObstaclePathResult shortest_path_avoiding_convex_polygon(const std::vector<PointR>&polygon,const PointR&start,const PointR&target,Real eps=1e-12L){int n=(int)polygon.size();if(n<3)return{distance(start,target),{start,target},true};if(point_in_convex_polygon(polygon,start,eps)!=PointLocation::Outside||point_in_convex_polygon(polygon,target,eps)!=PointLocation::Outside)return{};int s=n,t=n+1,N=n+2;std::vector<std::vector<std::pair<int,Real>>>g(N);auto edge=[&](int a,int b,Real w){g[a].push_back({b,w});g[b].push_back({a,w});};for(int i=0;i<n;++i)edge(i,(i+1)%n,distance(polygon[i],polygon[(i+1)%n]));if(!segment_intersects_convex_polygon_interior(polygon,start,target,eps))edge(s,t,distance(start,target));for(int i:convex_polygon_visible_vertices_ccw(polygon,start,eps))edge(s,i,distance(start,polygon[i]));for(int i:convex_polygon_visible_vertices_ccw(polygon,target,eps))edge(t,i,distance(target,polygon[i]));std::vector<Real>d(N,std::numeric_limits<Real>::infinity());std::vector<int>par(N,-1);using Q=std::pair<Real,int>;std::priority_queue<Q,std::vector<Q>,std::greater<Q>>q;d[s]=0;q.push({0,s});while(!q.empty()){auto [du,u]=q.top();q.pop();if(du!=d[u])continue;for(auto [v,w]:g[u])if(d[v]>du+w){d[v]=du+w;par[v]=u;q.push({d[v],v});}}if(!std::isfinite(d[t]))return{};std::vector<PointR>path;for(int u=t;u!=-1;u=par[u])path.push_back(u==s?start:u==t?target:polygon[u]);std::reverse(path.begin(),path.end());return{d[t],path,path.size()==2};}
inline Real distance_between_convex_polygons(const std::vector<PointR>&a,const std::vector<PointR>&b,Real eps=1e-12L){if(a.empty()||b.empty())return std::numeric_limits<Real>::infinity();if(!convex_polygons_disjoint(a,b,false,eps))return 0;Real ans=std::numeric_limits<Real>::infinity();for(size_t i=0;i<a.size();++i)for(size_t j=0;j<b.size();++j)ans=std::min(ans,segment_distance(a[i],a[(i+1)%a.size()],b[j],b[(j+1)%b.size()]));return ans;}

inline Real maximum_nonvisible_observer_height(const std::vector<PointI>&buildings){if(buildings.size()<2)return-1;for(size_t i=1;i<buildings.size();++i)if(buildings[i-1].x>=buildings[i].x)throw std::invalid_argument("x order");Real ans=-std::numeric_limits<Real>::infinity();for(size_t i=1;i<buildings.size();++i){Real x0=buildings[i-1].x,y0=buildings[i-1].y,x1=buildings[i].x,y1=buildings[i].y;ans=std::max(ans,(y0*x1-y1*x0)/(x1-x0));}return ans<0?-1:ans;}
