struct RectangleUnionMeasure{Real area{0},perimeter{0};};
inline RectangleUnionMeasure axis_aligned_rectangle_union_measure(const std::vector<BoundingBoxR>&rectangles){struct E{Real x,y1,y2;int delta;};std::vector<E>e;std::vector<Real>ys;for(auto r:rectangles)if(!r.empty&&r.min_x<r.max_x&&r.min_y<r.max_y){e.push_back({r.min_x,r.min_y,r.max_y,1});e.push_back({r.max_x,r.min_y,r.max_y,-1});ys.push_back(r.min_y);ys.push_back(r.max_y);}if(e.empty())return{};std::sort(ys.begin(),ys.end());ys.erase(std::unique(ys.begin(),ys.end()),ys.end());std::sort(e.begin(),e.end(),[](const E&a,const E&b){return a.x<b.x||(a.x==b.x&&a.delta>b.delta);});int n=(int)ys.size()-1;std::vector<int>cover(4*n);std::vector<Real>len(4*n);std::vector<int>segments(4*n);std::vector<char>left(4*n),right(4*n);std::function<void(int,int,int)>pull=[&](int v,int l,int r){if(cover[v]){len[v]=ys[r]-ys[l];segments[v]=1;left[v]=right[v]=1;}else if(r-l==1){len[v]=0;segments[v]=0;left[v]=right[v]=0;}else{len[v]=len[v*2]+len[v*2+1];segments[v]=segments[v*2]+segments[v*2+1]-(right[v*2]&&left[v*2+1]);left[v]=left[v*2];right[v]=right[v*2+1];}};std::function<void(int,int,int,int,int,int)>add=[&](int v,int l,int r,int ql,int qr,int d){if(qr<=l||r<=ql)return;if(ql<=l&&r<=qr)cover[v]+=d;else{int m=(l+r)/2;add(v*2,l,m,ql,qr,d);add(v*2+1,m,r,ql,qr,d);}pull(v,l,r);};RectangleUnionMeasure out;Real previous_x=e[0].x;size_t i=0;while(i<e.size()){Real x=e[i].x,dx=x-previous_x;out.area+=len[1]*dx;out.perimeter+=2*segments[1]*dx;Real before=len[1];size_t j=i;while(j<e.size()&&e[j].x==x&&e[j].delta>0){int l=std::lower_bound(ys.begin(),ys.end(),e[j].y1)-ys.begin(),r=std::lower_bound(ys.begin(),ys.end(),e[j].y2)-ys.begin();add(1,0,n,l,r,e[j].delta);out.perimeter+=std::fabs(len[1]-before);before=len[1];++j;}while(j<e.size()&&e[j].x==x){int l=std::lower_bound(ys.begin(),ys.end(),e[j].y1)-ys.begin(),r=std::lower_bound(ys.begin(),ys.end(),e[j].y2)-ys.begin();add(1,0,n,l,r,e[j].delta);out.perimeter+=std::fabs(len[1]-before);before=len[1];++j;}previous_x=x;i=j;}return out;}
inline Real axis_aligned_rectangle_union_area(const std::vector<BoundingBoxR>&rectangles){return axis_aligned_rectangle_union_measure(rectangles).area;}inline Real axis_aligned_rectangle_union_perimeter(const std::vector<BoundingBoxR>&rectangles){return axis_aligned_rectangle_union_measure(rectangles).perimeter;}

